// ColorCode represents terminal colors
type ColorCode struct {
	noColor bool
}

func newColor(noColor bool) *ColorCode {
	return &ColorCode{noColor: noColor}
}

func (c *ColorCode) colorize(code string, s string) string {
	if c.noColor {
		return s
	}
	return fmt.Sprintf("\033[%sm%s\033[0m", code, s)
}

func (c *ColorCode) green(s string) string {
	return c.colorize("92", s)
}

func (c *ColorCode) red(s string) string {
	return c.colorize("91", s)
}

func (c *ColorCode) yellow(s string) string {
	return c.colorize("93", s)
}

func (c *ColorCode) darkRed(s string) string {
	return c.colorize("31", s)
}

func (c *ColorCode) steelBlue(s string) string {
	return c.colorize("38;5;103", s)
}

func (c *ColorCode) statusColor(status TestStatus) string {
	switch status {
	case StatusPass:
		return c.green(status.String())
	case StatusFail:
		return c.red(status.String())
	case StatusSkip, StatusNoTest:
		return c.yellow(status.String())
	case StatusPanic:
		return c.red(status.String())
	default:
		return status.String()
	}
}

// Table represents a table of data
type Table struct {
	headers []string
	rows    [][]string
	format  string // "basic", "plain", "markdown"
	color   *ColorCode
}

func newTable(format string, color *ColorCode) *Table {
	return &Table{format: format, color: color}
}

func (t *Table) setHeaders(headers []string) {
	t.headers = headers
}

func (t *Table) addRow(row []string) {
	t.rows = append(t.rows, row)
}

func (t *Table) render(w io.Writer) {
	if len(t.headers) == 0 && len(t.rows) == 0 {
		return
	}

	// Calculate column widths (using visible character count)
	numCols := len(t.headers)
	widths := make([]int, numCols)
	for i, h := range t.headers {
		widths[i] = visibleLen(h)
	}
	for _, row := range t.rows {
		for i, cell := range row {
			if i < numCols {
				vlen := visibleLen(cell)
				if vlen > widths[i] {
					widths[i] = vlen
				}
			}
		}
	}

	switch t.format {
	case "plain":
		t.renderPlain(w, widths)
	case "markdown":
		t.renderMarkdown(w, widths)
	default:
		t.renderBasic(w, widths)
	}
}

// visibleLen returns the visible character count of a string (ignoring ANSI escape codes)
func visibleLen(s string) int {
	// Remove ANSI escape codes
	result := 0
	inEscape := false
	for i := 0; i < len(s); {
		if s[i] == '\033' {
			inEscape = true
			i++
			continue
		}
		if inEscape {
			if s[i] == 'm' {
				inEscape = false
			}
			i++
			continue
		}
		r, size := utf8.DecodeRuneInString(s[i:])
		_ = r
		result++
		i += size
	}
	return result
}

// padRight pads a string to the given visible length (accounting for ANSI codes)
func padRight(s string, width int) string {
	vlen := visibleLen(s)
	if vlen >= width {
		return s
	}
	return s + strings.Repeat(" ", width-vlen)
}

// center centers a string in the given visible width
func center(s string, width int) string {
	vlen := visibleLen(s)
	if vlen >= width {
		return s
	}
	total := width - vlen
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func (t *Table) renderBasic(w io.Writer, widths []int) {
	// Unicode box-drawing chars
	// Top: ╭─┬─╮
	// Mid: ├─┼─┤  
	// Bot: ╰─┴─╯
	// Row: │ │ │

	n := len(widths)

	// Build separator parts
	buildLine := func(left, mid, right, fill string) string {
		var sb strings.Builder
		sb.WriteString(left)
		for i, w := range widths {
			sb.WriteString(strings.Repeat(fill, w+2))
			if i < n-1 {
				sb.WriteString(mid)
			}
		}
		sb.WriteString(right)
		return sb.String()
	}

	topLine := buildLine("╭", "┬", "╮", "─")
	midLine := buildLine("├", "┼", "┤", "─")
	botLine := buildLine("╰", "┴", "╯", "─")

	fmt.Fprintln(w, topLine)

	// Header row
	var sb strings.Builder
	sb.WriteString("│")
	for i, h := range t.headers {
		sb.WriteString(" ")
		sb.WriteString(center(h, widths[i]))
		sb.WriteString(" │")
	}
	fmt.Fprintln(w, sb.String())

	fmt.Fprintln(w, midLine)

	// Data rows
	for _, row := range t.rows {
		var rb strings.Builder
		rb.WriteString("│")
		for i := 0; i < n; i++ {
			rb.WriteString(" ")
			if i < len(row) {
				rb.WriteString(center(row[i], widths[i]))
			} else {
				rb.WriteString(strings.Repeat(" ", widths[i]))
			}
			rb.WriteString(" │")
		}
		fmt.Fprintln(w, rb.String())
	}

	fmt.Fprintln(w, botLine)
}

func (t *Table) renderPlain(w io.Writer, widths []int) {
	n := len(widths)

	renderRow := func(cells []string) {
		var sb strings.Builder
		for i := 0; i < n; i++ {
			cell := ""
			if i < len(cells) {
				cell = cells[i]
			}
			sb.WriteString(" ")
			sb.WriteString(center(cell, widths[i]))
			sb.WriteString(" ")
			if i < n-1 {
				sb.WriteString(" ")
			}
		}
		fmt.Fprintln(w, sb.String())
	}

	// Build separator line of spaces
	var sepSB strings.Builder
	for i, w := range widths {
		sepSB.WriteString(strings.Repeat(" ", w+2))
		if i < n-1 {
			sepSB.WriteString(" ")
		}
	}
	sep := sepSB.String()

	renderRow(t.headers)
	fmt.Fprintln(w, sep)
	for _, row := range t.rows {
		renderRow(row)
	}
}

func (t *Table) renderMarkdown(w io.Writer, widths []int) {
	n := len(widths)

	renderRow := func(cells []string) {
		var sb strings.Builder
		sb.WriteString("|")
		for i := 0; i < n; i++ {
			cell := ""
			if i < len(cells) {
				cell = cells[i]
			}
			sb.WriteString(center(cell, widths[i]+2))
			sb.WriteString("|")
		}
		fmt.Fprintln(w, sb.String())
	}

	renderRow(t.headers)

	// Separator line
	var sepSB strings.Builder
	sepSB.WriteString("|")
	for i, w := range widths {
		sepSB.WriteString(strings.Repeat("-", w+2))
		if i < n-1 {
			sepSB.WriteString("|")
		}
	}
	sepSB.WriteString("|")
	fmt.Fprintln(w, sepSB.String())

	for _, row := range t.rows {
		renderRow(row)
	}
}

// Config holds the command-line configuration
type Config struct {
	all             bool
	pass            bool
	skip            bool
	notests         bool
	smallscreen     bool
	slow            int
	sort            string
	nocolor         bool
	format          string
	file            string
	follow          bool
	followOutput    string
	includeTimestamp bool
	progress        bool
	compare         string
	trimpath        string
}

var config Config

func init() {
	flag.BoolVar(&config.all, "all", false, "Display table event for pass and skip. (Failed items always displayed)")
	flag.BoolVar(&config.pass, "pass", false, "Display table for passed tests.")
	flag.BoolVar(&config.skip, "skip", false, "Display table for skipped tests.")
	flag.BoolVar(&config.notests, "notests", false, "Display packages containing no test files or empty test files.")
	flag.BoolVar(&config.smallscreen, "smallscreen", false, "Split subtest names vertically to fit on smaller screens.")
	flag.IntVar(&config.slow, "slow", 0, "Number of slowest tests to display. Default is 0, display all.")
	flag.StringVar(&config.sort, "sort", "name", "Sort table output by attribute [name, elapsed, cover]. Default is name.")
	flag.BoolVar(&config.nocolor, "nocolor", false, "Disable all colors. (NO_COLOR also supported)")
	flag.StringVar(&config.format, "format", "basic", "The output format for tables [basic, plain, markdown]. Default is basic.")
	flag.StringVar(&config.file, "file", "", "Read test output from a file.")
	flag.BoolVar(&config.follow, "follow", false, "Follow raw output from go test to stdout.")
	flag.StringVar(&config.followOutput, "follow-output", "", "Write raw output from go test to a file (takes precedence over -follow).")
	flag.BoolVar(&config.includeTimestamp, "include-timestamp", false, "Include timestamps in follow output.")
	flag.BoolVar(&config.progress, "progress", false, "Print a single summary line for each package. Useful for long running test suites.")
	flag.StringVar(&config.compare, "compare", "", "Compare against a previous test output file. (experimental)")
	flag.StringVar(&config.trimpath, "trimpath", "", "Remove path prefix from package names in output, simplifying their display.")
}

func usage() {
	fmt.Fprintf(os.Stdout, `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`)
}

func main() {
	flag.Usage = usage

	// Handle -h and -v manually (before parsing flags)
	for _, arg := range os.Args[1:] {
		if arg == "-h" || arg == "--h" {
			usage()
			os.Exit(0)
		}
		if arg == "-v" || arg == "--v" {
			fmt.Fprintln(os.Stdout, "tparse version: (devel)")
			os.Exit(0)
		}
	}

	if err := flag.CommandLine.Parse(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "error parsing flags: %v\n", err)
		usage()
		os.Exit(2)
	}

	// Check NO_COLOR env var
	if os.Getenv("NO_COLOR") != "" {
		config.nocolor = true
	}

	var reader io.Reader
	var followWriter io.Writer

	if config.followOutput != "" {
		f, err := os.Create(config.followOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error creating follow-output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		followWriter = f
	} else if config.follow {
		followWriter = os.Stdout
	}

	if config.file != "" {
		f, err := os.Open(config.file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error opening file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		reader = f
	} else {
		// Check if stdin is a pipe
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stdout, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(0)
		}
		reader = os.Stdin
	}

	exitCode, err := run(reader, os.Stdout, followWriter)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	os.Exit(exitCode)
}

func trimPackageName(pkg string) string {
	if config.trimpath == "" {
		return pkg
	}
	if strings.HasPrefix(pkg, config.trimpath) {
		return pkg[len(config.trimpath):]
	}
	return pkg
}

func packageDisplay(pkg string) string {
	pkg = trimPackageName(pkg)
	if config.smallscreen {
		// Use just the last component
		parts := strings.Split(pkg, "/")
		return parts[len(parts)-1]
	}
	return pkg
}

func run(reader io.Reader, w io.Writer, followWriter io.Writer) (int, error) {
	// Parse events
	events, err := parseEvents(reader, followWriter)
	if err != nil {
		return 1, err
	}

	if len(events) == 0 {
		fmt.Fprintln(w, "no parsable events: Make sure to run go test with -json flag")
		return 1, nil
	}

	// Process events into package results
	packages := processEvents(events)

	if len(packages) == 0 {
		fmt.Fprintln(w, "no parsable events: Make sure to run go test with -json flag")
		return 1, nil
	}

	// Sort packages by name (or the sort field for the summary table)
	sortedPkgs := sortPackages(packages)

	color := newColor(config.nocolor)

	failCount := 0

	// Print test table (for -all, -pass, -skip flags)
	printTestTable := config.all || config.pass || config.skip

	if config.format == "markdown" {
		// Markdown format - print per-package
		for _, pkg := range sortedPkgs {
			if pkg.IsNoTest {
				continue
			}
			if pkg.IsPanic {
				continue
			}
			// Show package header in markdown only if we have test results
			showTests := config.all || config.pass || config.skip || pkg.Status == StatusFail
			if !showTests {
				continue
			}

			// Filter tests to show
			var testsToShow []*TestResult
			for _, tr := range pkg.Tests {
				if shouldShowTest(tr) {
					testsToShow = append(testsToShow, tr)
				}
			}

			if len(testsToShow) == 0 && pkg.Status != StatusFail {
				continue
			}

			fmt.Fprintf(w, "## 📦 Package **`%s`**\n\n", packageDisplay(pkg.Package))

			// Count stats
			passCount := 0
			skipCount := 0
			failC := 0
			for _, tr := range pkg.Tests {
				switch tr.Status {
				case StatusPass:
					passCount++
				case StatusSkip:
					skipCount++
				case StatusFail:
					failC++
				}
			}
			fmt.Fprintf(w, "Tests: ✓ %d passed | %d skipped | %d failed\n\n", passCount, skipCount, failC)

			if len(testsToShow) > 0 {
				fmt.Fprintln(w, "<details>")
				fmt.Fprintln(w, "")
				fmt.Fprintln(w, "<summary>Click for test summary</summary>")
				fmt.Fprintln(w, "")

				tbl := newTable("markdown", color)
				tbl.setHeaders([]string{"Status", "Elapsed", "Test"})
				for _, tr := range testsToShow {
					tbl.addRow([]string{tr.Status.String(), fmt.Sprintf("  %.2f  ", tr.Elapsed), tr.Test})
				}
				tbl.render(w)
				fmt.Fprintln(w, "</details>")
				fmt.Fprintln(w, "")
			}
			fmt.Fprintln(w, "")
		}

		// Print package failures
		for _, pkg := range sortedPkgs {
			if pkg.IsPanic {
				continue
			}
			if pkg.Status == StatusFail || hasFailed(pkg) {
				failedTests := getFailedTests(pkg)
				if len(failedTests) > 0 {
					fmt.Fprintf(w, "## FAIL • %s\n\n", packageDisplay(pkg.Package))
					fmt.Fprintln(w, "```")
					for _, tr := range failedTests {
						printTestOutput(w, pkg, tr)
					}
					fmt.Fprintln(w, "```")
					fmt.Fprintln(w, "")
					failCount++
				}
			}
		}

		// Print final summary table
		printSummaryTable(w, sortedPkgs, color)

	} else {
		// Basic/plain format

		// Collect all tests to show across all packages (for the test table)
		if printTestTable {
			var allTests []*testEntry
			var prevPkg string
			for _, pkg := range sortedPkgs {
				if pkg.IsNoTest || pkg.IsPanic {
					continue
				}
				for _, tr := range pkg.Tests {
					if !shouldShowTest(tr) {
						continue
					}
					entry := &testEntry{
						pkg:  pkg,
						test: tr,
					}
					if pkg.Package != prevPkg && prevPkg != "" {
						entry.newPkg = true
					}
					if prevPkg == "" || pkg.Package != prevPkg {
						prevPkg = pkg.Package
					}
					allTests = append(allTests, entry)
				}
			}

			if len(allTests) > 0 {
				// Apply slow filter
				if config.slow > 0 {
					// Sort by elapsed descending, take top N
					sort.Slice(allTests, func(i, j int) bool {
						return allTests[i].test.Elapsed > allTests[j].test.Elapsed
					})
					if config.slow < len(allTests) {
						allTests = allTests[:config.slow]
					}
				}

				printTestTableBasic(w, allTests, color)
			}
		}

		// Print package failure output
		for _, pkg := range sortedPkgs {
			if pkg.IsPanic {
				printPanicBox(w, pkg, color)
				failCount++
				continue
			}

			// Progress output
			if config.progress {
				statusStr := "PASS"
				if pkg.Status == StatusFail {
					statusStr = "FAIL"
				} else if pkg.Status == StatusPanic {
					statusStr = "PANIC"
				}
				fmt.Fprintf(w, "[%s]\t%9.2fs\t%s\n", statusStr, pkg.Elapsed, packageDisplay(pkg.Package))
			}

			if pkg.Status == StatusFail || hasFailed(pkg) {
				failedTests := getFailedTests(pkg)
				printFailBox(w, pkg, failedTests, color)
				if pkg.Status == StatusFail {
					failCount++
				}
			}
		}

		// Print final summary table
		printSummaryTable(w, sortedPkgs, color)
	}

	if failCount > 0 {
		return 1, nil
	}
	return 0, nil
}

type testEntry struct {
	pkg    *PackageResult
	test   *TestResult
	newPkg bool
}

func shouldShowTest(tr *TestResult) bool {
	if config.all {
		return true
	}
	if tr.Status == StatusFail {
		return true
	}
	if config.pass && tr.Status == StatusPass {
		return true
	}
	if config.skip && tr.Status == StatusSkip {
		return true
	}
	return false
}

func hasFailed(pkg *PackageResult) bool {
	for _, tr := range pkg.Tests {
		if tr.Status == StatusFail {
			return true
		}
	}
	return false
}

func getFailedTests(pkg *PackageResult) []*TestResult {
	var failed []*TestResult
	for _, tr := range pkg.Tests {
		if tr.Status == StatusFail {
			failed = append(failed, tr)
		}
	}
	// Sort alphabetically by test name
	sort.Slice(failed, func(i, j int) bool {
		return failed[i].Test < failed[j].Test
	})
	return failed
}

func printTestTableBasic(w io.Writer, entries []*testEntry, color *ColorCode) {
	tbl := newTable(config.format, color)
	tbl.setHeaders([]string{"Status", "Elapsed", "Test", "Package"})

	for i, e := range entries {
		if e.newPkg && i > 0 {
			tbl.addRow([]string{"", "", "", ""})
		}
		tbl.addRow([]string{
			color.statusColor(e.test.Status),
			fmt.Sprintf("%.2f", e.test.Elapsed),
			e.test.Test,
			packageDisplay(e.pkg.Package),
		})
	}

	tbl.render(w)
}

func printFailBox(w io.Writer, pkg *PackageResult, failedTests []*TestResult, color *ColorCode) {
	var statusStr string
	if pkg.Status == StatusFail {
		statusStr = "FAIL"
	} else {
		statusStr = "PASS"
	}

	content := fmt.Sprintf("   %s  package: %s   ", statusStr, pkg.Package)
	border := strings.Repeat("━", utf8.RuneCountInString(content))

	fmt.Fprintf(w, "%s\n", color.steelBlue("┏"+border+"┓"))
	fmt.Fprintf(w, "%s   %s  package: %s   %s\n",
		color.steelBlue("┃"),
		color.red(statusStr),
		pkg.Package,
		color.steelBlue("┃"))
	fmt.Fprintf(w, "%s\n", color.steelBlue("┗"+border+"┛"))
	fmt.Fprintln(w)

	for i, tr := range failedTests {
		if i > 0 {
			fmt.Fprintln(w, strings.Repeat("─", 96))
			fmt.Fprintln(w, strings.Repeat(" ", 96))
		}
		printTestOutput(w, pkg, tr)
	}
}

func printPanicBox(w io.Writer, pkg *PackageResult, color *ColorCode) {
	testPart := ""
	if pkg.PanicTest != "" {
		testPart = " • " + pkg.PanicTest
	}

	content := fmt.Sprintf("   PANIC  package: %s%s   ", pkg.Package, testPart)
	border := strings.Repeat("━", utf8.RuneCountInString(content))

	fmt.Fprintf(w, "%s\n", color.steelBlue("┏"+border+"┓"))
	fmt.Fprintf(w, "%s   %s  package: %s%s   %s\n",
		color.steelBlue("┃"),
		color.red("PANIC"),
		pkg.Package,
		testPart,
		color.steelBlue("┃"))
	fmt.Fprintf(w, "%s\n", color.steelBlue("┗"+border+"┛"))

	// Print all the output
	for _, line := range pkg.Output {
		fmt.Fprint(w, line)
	}
	fmt.Fprintln(w)
}

func printTestOutput(w io.Writer, pkg *PackageResult, tr *TestResult) {
	color := newColor(config.nocolor)
	for i, line := range tr.Output {
		if i == 0 && strings.HasPrefix(strings.TrimSpace(line), "--- FAIL:") {
			fmt.Fprint(w, color.darkRed(strings.TrimRight(line, "\n")))
			fmt.Fprintln(w)
		} else if i == 0 && strings.HasPrefix(strings.TrimSpace(line), "  --- FAIL:") {
			fmt.Fprint(w, color.darkRed(strings.TrimRight(line, "\n")))
			fmt.Fprintln(w)
		} else {
			fmt.Fprint(w, strings.TrimRight(line, "\n"))
			fmt.Fprintln(w)
		}
	}
	fmt.Fprintln(w)
}

func printSummaryTable(w io.Writer, packages []*PackageResult, color *ColorCode) {
	tbl := newTable(config.format, color)
	tbl.setHeaders([]string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"})

	for _, pkg := range packages {
		var statusStr string
		var passStr, failStr, skipStr, coverStr string

		if pkg.IsPanic {
			statusStr = color.statusColor(StatusPanic)
			passStr = "--"
			failStr = "--"
			skipStr = "--"
			coverStr = "--"
		} else if pkg.IsNoTest {
			statusStr = color.statusColor(StatusNoTest)
			passStr = "--"
			failStr = "--"
			skipStr = "--"
			coverStr = "--"
		} else {
			statusStr = color.statusColor(pkg.Status)
			passStr = fmt.Sprintf("%d", pkg.Pass)
			failStr = fmt.Sprintf("%d", pkg.Fail)
			skipStr = fmt.Sprintf("%d", pkg.Skip)
			coverStr = pkg.Cover
			if coverStr == "" {
				coverStr = "--"
			}
		}

		elapsed := fmt.Sprintf("%.2fs", pkg.Elapsed)
		pkgName := packageDisplay(pkg.Package)

		tbl.addRow([]string{statusStr, elapsed, pkgName, coverStr, passStr, failStr, skipStr})

		if pkg.IsNoTest {
			// Add a second row with the no-test message
			// Extract message from output
			msg := "[no test files]"
			for _, line := range pkg.Output {
				line = strings.TrimSpace(line)
				if strings.Contains(line, "[no test files]") {
					msg = "[no test files]"
					break
				} else if strings.Contains(line, "[no tests to run]") {
					msg = "[no tests to run]"
					break
				}
			}
			tbl.addRow([]string{"", "", msg, "", "", "", ""})
		}
	}

	tbl.render(w)
}

func sortPackages(packages map[string]*PackageResult) []*PackageResult {
	result := make([]*PackageResult, 0, len(packages))
	for _, pkg := range packages {
		result = append(result, pkg)
	}

	switch config.sort {
	case "elapsed":
		sort.Slice(result, func(i, j int) bool {
			return result[i].Elapsed > result[j].Elapsed
		})
	case "cover":
		sort.Slice(result, func(i, j int) bool {
			ci := parseCover(result[i].Cover)
			cj := parseCover(result[j].Cover)
			return ci > cj
		})
	default: // "name"
		sort.Slice(result, func(i, j int) bool {
			return result[i].Package < result[j].Package
		})
	}

	return result
}

func parseCover(s string) float64 {
	if s == "" || s == "--" {
		return -1
	}
	s = strings.TrimSuffix(s, "%")
	var f float64
	fmt.Sscanf(s, "%f", &f)
	return f
}

func parseEvents(reader io.Reader, followWriter io.Writer) ([]*TestEvent, error) {
	var events []*TestEvent
	scanner := bufio.NewScanner(reader)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		var event TestEvent
		if err := json.Unmarshal([]byte(line), &event); err != nil {
			continue
		}

		events = append(events, &event)

		// Follow output
		if followWriter != nil && event.Action == "output" {
			if config.includeTimestamp {
				timestamp := event.Time.UTC().Format("2006-01-02T15:04:05Z")
				fmt.Fprintf(followWriter, "%s %s", timestamp, event.Output)
			} else {
				fmt.Fprint(followWriter, event.Output)
			}
		}
	}

	return events, scanner.Err()
}

func processEvents(events []*TestEvent) map[string]*PackageResult {
	packages := make(map[string]*PackageResult)
	// Track test results per package
	// We need to map (package, test) -> TestResult
	testResults := make(map[string]map[string]*TestResult)

	for _, event := range events {
		pkg := event.Package
		if pkg == "" {
			continue
		}

		if _, ok := packages[pkg]; !ok {
			packages[pkg] = &PackageResult{
				Package:         pkg,
				Cover:           "",
				UnfinishedTests: make(map[string]*TestResult),
			}
			testResults[pkg] = make(map[string]*TestResult)
		}

		pkgResult := packages[pkg]

		switch event.Action {
		case "run":
			if event.Test != "" {
				tr := &TestResult{
					Package: pkg,
					Test:    event.Test,
					Status:  StatusUnknown,
				}
				testResults[pkg][event.Test] = tr
				pkgResult.UnfinishedTests[event.Test] = tr
			}

		case "output":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					tr.Output = append(tr.Output, event.Output)
				}
			} else {
				// Package-level output
				pkgResult.Output = append(pkgResult.Output, event.Output)

				// Check for coverage
				if strings.Contains(event.Output, "coverage:") {
					cov := extractCoverage(event.Output)
					if cov != "" {
						pkgResult.Cover = cov
					}
				}
			}

		case "pass":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					tr.Status = StatusPass
					tr.Elapsed = event.Elapsed
					delete(pkgResult.UnfinishedTests, event.Test)
					pkgResult.Tests = append(pkgResult.Tests, tr)
					pkgResult.Pass++
				}
			} else {
				pkgResult.Status = StatusPass
				pkgResult.Elapsed = event.Elapsed
			}

		case "fail":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					// Check for panic in test output
					hasPanic := false
					for _, line := range tr.Output {
						if strings.HasPrefix(strings.TrimSpace(line), "panic:") {
							hasPanic = true
							break
						}
					}
					if hasPanic {
						tr.Status = StatusPanic
						pkgResult.IsPanic = true
						pkgResult.PanicTest = event.Test
						// Add all the output to pkg output
						pkgResult.Output = append(tr.Output, pkgResult.Output...)
					} else {
						tr.Status = StatusFail
						pkgResult.Tests = append(pkgResult.Tests, tr)
						pkgResult.Fail++
					}
					tr.Elapsed = event.Elapsed
					delete(pkgResult.UnfinishedTests, event.Test)
				}
			} else {
				pkgResult.Elapsed = event.Elapsed
				if !pkgResult.IsPanic {
					pkgResult.Status = StatusFail
				}
			}

		case "skip":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					tr.Status = StatusSkip
					tr.Elapsed = event.Elapsed
					delete(pkgResult.UnfinishedTests, event.Test)
					pkgResult.Tests = append(pkgResult.Tests, tr)
					pkgResult.Skip++
				}
			} else {
				// Package skipped (no test files)
				pkgResult.IsNoTest = true
				pkgResult.Status = StatusSkip
				pkgResult.Elapsed = event.Elapsed
			}

		case "build-fail":
			pkgResult.Status = StatusFail
			pkgResult.Fail = 1
		}
	}

	// Process unfinished tests - tests that had run events but no result
	for _, pkgResult := range packages {
		for testName, tr := range pkgResult.UnfinishedTests {
			_ = testName
			if tr.Status == StatusUnknown {
				tr.Status = StatusFail
				pkgResult.Tests = append(pkgResult.Tests, tr)
				pkgResult.Fail++
			}
		}
	}

	// For PANIC packages, check package-level output for panics too
	for _, pkgResult := range packages {
		if !pkgResult.IsPanic {
			for _, line := range pkgResult.Output {
				if strings.HasPrefix(strings.TrimSpace(line), "panic:") {
					pkgResult.IsPanic = true
					pkgResult.Status = StatusPanic
					break
				}
			}
		}
		if pkgResult.IsPanic {
			pkgResult.Status = StatusPanic
		}
	}

	return packages
}

func extractCoverage(output string) string {
	// Format: "coverage: X.X% of statements"
	idx := strings.Index(output, "coverage: ")
	if idx < 0 {
		return ""
	}
	rest := output[idx+len("coverage: "):]
	end := strings.Index(rest, " ")
	if end < 0 {
		return strings.TrimSpace(rest)
	}
	return rest[:end]
}

func roundFloat(f float64, decimals int) float64 {
	pow := math.Pow(10, float64(decimals))
	return math.Round(f*pow) / pow
}

func formatElapsed(e float64) string {
	return fmt.Sprintf("%.2f", e)
}

func formatElapsedWithS(e float64) string {
	return fmt.Sprintf("%.2fs", e)
}
