# Now let me understand what exactly constitutes "header content" vs "body content":
# - Header: any line that contains "--- FAIL:", "--- PASS:", "--- SKIP:" (these are test result lines)
# - Body: all other lines

# The "--- FAIL:" lines appear in go test output as:
# "--- FAIL: TestFoo (0.10s)" for top-level tests
# "    --- FAIL: TestFoo/sub1 (0.01s)" for subtests (4 spaces indent)
# "        --- FAIL: TestFoo/sub1/deep1 (0.005s)" for sub-subtests (8 spaces indent)

# In the DISPLAY:
# - Top-level: "--- FAIL: TestFoo" (0 spaces)
# - Level 2: "  --- FAIL: TestFoo/sub1" (2 spaces)
# - Level 3: "    --- FAIL: TestFoo/sub1/deep1" (4 spaces)

# The indent in display = (slash count in test name) * 2

# For the parent test ITSELF (TestFoo):
# Its output is "--- FAIL: TestFoo (0.10s)\n" (no leading spaces)
# Display: "--- FAIL: TestFoo (0.10s)" (no indent needed)

# For sub1:
# Its output is "    --- FAIL: TestFoo/sub1 (0.01s)\n" (4 spaces leading)
# Display: "  --- FAIL: TestFoo/sub1 (0.01s)" (2 spaces = 1 slash * 2)

# For deep1 (TestFoo/sub1/deep1):
# Its output is "        --- FAIL: TestFoo/sub1/deep1 (0.005s)\n" (8 spaces leading)
# Display: "    --- FAIL: TestFoo/sub1/deep1 (0.005s)" (4 spaces = 2 slashes * 2)

# So when displaying the "--- FAIL:" line, the original leading spaces are REPLACED
# with (slash count) * 2 spaces.

# Now I'll rewrite the implementation with this understanding.

# But wait - what about the "body lines" (non-header output)?
# In sub1's output: "    sub1 body line" (4 spaces)
# Display: "    sub1 body line" (same 4 spaces, UNCHANGED)

# In deep1's output: "            deep1 failed" (12 spaces)
# Display: "            deep1 failed" (same 12 spaces, UNCHANGED)

# So body lines are NEVER modified - displayed as-is.

# Now let me write the complete implementation:
# I'll do a major rewrite of main.go

cat > /home/agent/tparse/main.go << 'GOEOF'
package main

import (
	"bufio"
	"encoding/json"
	"flag"
	"fmt"
	"io"
	"os"
	"sort"
	"strings"
	"time"
	"unicode/utf8"
)

// TestEvent represents a single event from `go test -json`
type TestEvent struct {
	Time    time.Time
	Action  string
	Package string
	Test    string
	Elapsed float64
	Output  string
}

// TestStatus represents the status of a test
type TestStatus int

const (
	StatusUnknown TestStatus = iota
	StatusPass
	StatusFail
	StatusSkip
	StatusPanic
	StatusNoTest
)

func (s TestStatus) String() string {
	switch s {
	case StatusPass:
		return "PASS"
	case StatusFail:
		return "FAIL"
	case StatusSkip:
		return "SKIP"
	case StatusPanic:
		return "PANIC"
	case StatusNoTest:
		return "NOTEST"
	default:
		return ""
	}
}

// TestResult represents the result of a single test
type TestResult struct {
	Package string
	Test    string
	Status  TestStatus
	Elapsed float64
	Output  []string // raw output lines
}

// PackageResult represents the result of a package
type PackageResult struct {
	Package  string
	Status   TestStatus
	Elapsed  float64
	Cover    string
	Pass     int
	Fail     int
	Skip     int
	Tests    []*TestResult        // completed tests
	IsPanic  bool
	IsNoTest bool
	PanicTest string
	Output   []string             // package-level output
	// Map from test name to test result (for all tests)
	testMap  map[string]*TestResult
}

// ColorCode represents terminal colors
type ColorCode struct {
	noColor bool
}

func newColor(noColor bool) *ColorCode {
	return &ColorCode{noColor: noColor}
}

func (c *ColorCode) colorize(code string, s string) string {
	if c.noColor {
		return s
	}
	return fmt.Sprintf("\033[%sm%s\033[0m", code, s)
}

func (c *ColorCode) green(s string) string {
	return c.colorize("92", s)
}

func (c *ColorCode) red(s string) string {
	return c.colorize("91", s)
}

func (c *ColorCode) yellow(s string) string {
	return c.colorize("93", s)
}

func (c *ColorCode) darkRed(s string) string {
	return c.colorize("31", s)
}

func (c *ColorCode) steelBlue(s string) string {
	return c.colorize("38;5;103", s)
}

func (c *ColorCode) statusColor(status TestStatus) string {
	switch status {
	case StatusPass:
		return c.green(status.String())
	case StatusFail:
		return c.red(status.String())
	case StatusSkip, StatusNoTest:
		return c.yellow(status.String())
	case StatusPanic:
		return c.red(status.String())
	default:
		return status.String()
	}
}

// visibleLen returns the visible character count of a string (ignoring ANSI escape codes)
func visibleLen(s string) int {
	result := 0
	inEscape := false
	for i := 0; i < len(s); {
		if s[i] == '\033' {
			inEscape = true
			i++
			continue
		}
		if inEscape {
			if s[i] == 'm' {
				inEscape = false
			}
			i++
			continue
		}
		_, size := utf8.DecodeRuneInString(s[i:])
		result++
		i += size
	}
	return result
}

// center centers a string in the given visible width
func center(s string, width int) string {
	vlen := visibleLen(s)
	if vlen >= width {
		return s
	}
	total := width - vlen
	left := total / 2
	right := total - left
	return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

// Table represents a table of data
type Table struct {
	headers []string
	rows    [][]string
	format  string // "basic", "plain", "markdown"
	color   *ColorCode
}

func newTable(format string, color *ColorCode) *Table {
	return &Table{format: format, color: color}
}

func (t *Table) setHeaders(headers []string) {
	t.headers = headers
}

func (t *Table) addRow(row []string) {
	t.rows = append(t.rows, row)
}

func (t *Table) render(w io.Writer) {
	if len(t.headers) == 0 && len(t.rows) == 0 {
		return
	}

	numCols := len(t.headers)
	widths := make([]int, numCols)
	for i, h := range t.headers {
		widths[i] = visibleLen(h)
	}
	for _, row := range t.rows {
		for i, cell := range row {
			if i < numCols {
				vlen := visibleLen(cell)
				if vlen > widths[i] {
					widths[i] = vlen
				}
			}
		}
	}

	switch t.format {
	case "plain":
		t.renderPlain(w, widths)
	case "markdown":
		t.renderMarkdown(w, widths)
	default:
		t.renderBasic(w, widths)
	}
}

func (t *Table) renderBasic(w io.Writer, widths []int) {
	n := len(widths)

	buildLine := func(left, mid, right, fill string) string {
		var sb strings.Builder
		sb.WriteString(left)
		for i, w := range widths {
			sb.WriteString(strings.Repeat(fill, w+2))
			if i < n-1 {
				sb.WriteString(mid)
			}
		}
		sb.WriteString(right)
		return sb.String()
	}

	topLine := buildLine("╭", "┬", "╮", "─")
	midLine := buildLine("├", "┼", "┤", "─")
	botLine := buildLine("╰", "┴", "╯", "─")

	fmt.Fprintln(w, topLine)

	var sb strings.Builder
	sb.WriteString("│")
	for i, h := range t.headers {
		sb.WriteString(" ")
		sb.WriteString(center(h, widths[i]))
		sb.WriteString(" │")
	}
	fmt.Fprintln(w, sb.String())

	fmt.Fprintln(w, midLine)

	for _, row := range t.rows {
		var rb strings.Builder
		rb.WriteString("│")
		for i := 0; i < n; i++ {
			rb.WriteString(" ")
			if i < len(row) {
				rb.WriteString(center(row[i], widths[i]))
			} else {
				rb.WriteString(strings.Repeat(" ", widths[i]))
			}
			rb.WriteString(" │")
		}
		fmt.Fprintln(w, rb.String())
	}

	fmt.Fprintln(w, botLine)
}

func (t *Table) renderPlain(w io.Writer, widths []int) {
	n := len(widths)

	renderRow := func(cells []string) {
		var sb strings.Builder
		for i := 0; i < n; i++ {
			cell := ""
			if i < len(cells) {
				cell = cells[i]
			}
			sb.WriteString(" ")
			sb.WriteString(center(cell, widths[i]))
			sb.WriteString(" ")
			if i < n-1 {
				sb.WriteString(" ")
			}
		}
		fmt.Fprintln(w, sb.String())
	}

	var sepSB strings.Builder
	for i, w := range widths {
		sepSB.WriteString(strings.Repeat(" ", w+2))
		if i < n-1 {
			sepSB.WriteString(" ")
		}
	}
	sep := sepSB.String()

	renderRow(t.headers)
	fmt.Fprintln(w, sep)
	for _, row := range t.rows {
		renderRow(row)
	}
}

func (t *Table) renderMarkdown(w io.Writer, widths []int) {
	n := len(widths)

	renderRow := func(cells []string) {
		var sb strings.Builder
		sb.WriteString("|")
		for i := 0; i < n; i++ {
			cell := ""
			if i < len(cells) {
				cell = cells[i]
			}
			sb.WriteString(center(cell, widths[i]+2))
			sb.WriteString("|")
		}
		fmt.Fprintln(w, sb.String())
	}

	renderRow(t.headers)

	var sepSB strings.Builder
	sepSB.WriteString("|")
	for i, w := range widths {
		sepSB.WriteString(strings.Repeat("-", w+2))
		if i < n-1 {
			sepSB.WriteString("|")
		}
	}
	sepSB.WriteString("|")
	fmt.Fprintln(w, sepSB.String())

	for _, row := range t.rows {
		renderRow(row)
	}
}

// Config holds the command-line configuration
type Config struct {
	all              bool
	pass             bool
	skip             bool
	notests          bool
	smallscreen      bool
	slow             int
	sort             string
	nocolor          bool
	format           string
	file             string
	follow           bool
	followOutput     string
	includeTimestamp bool
	progress         bool
	compare          string
	trimpath         string
}

var config Config

func init() {
	flag.BoolVar(&config.all, "all", false, "")
	flag.BoolVar(&config.pass, "pass", false, "")
	flag.BoolVar(&config.skip, "skip", false, "")
	flag.BoolVar(&config.notests, "notests", false, "")
	flag.BoolVar(&config.smallscreen, "smallscreen", false, "")
	flag.IntVar(&config.slow, "slow", 0, "")
	flag.StringVar(&config.sort, "sort", "name", "")
	flag.BoolVar(&config.nocolor, "nocolor", false, "")
	flag.StringVar(&config.format, "format", "basic", "")
	flag.StringVar(&config.file, "file", "", "")
	flag.BoolVar(&config.follow, "follow", false, "")
	flag.StringVar(&config.followOutput, "follow-output", "", "")
	flag.BoolVar(&config.includeTimestamp, "include-timestamp", false, "")
	flag.BoolVar(&config.progress, "progress", false, "")
	flag.StringVar(&config.compare, "compare", "", "")
	flag.StringVar(&config.trimpath, "trimpath", "", "")
}

func usage() {
	fmt.Fprintf(os.Stdout, `Usage:
    go test ./... -json | tparse [options...]
    go test [packages...] -json | tparse [options...]
    go test [packages...] -json > pkgs.out ; tparse [options...] -file pkgs.out

Options:
    -h                 Show help.
    -v                 Show version.
    -all               Display table event for pass and skip. (Failed items always displayed)
    -pass              Display table for passed tests.
    -skip              Display table for skipped tests.
    -notests           Display packages containing no test files or empty test files.
    -smallscreen       Split subtest names vertically to fit on smaller screens.
    -slow              Number of slowest tests to display. Default is 0, display all.
    -sort              Sort table output by attribute [name, elapsed, cover]. Default is name.
    -nocolor           Disable all colors. (NO_COLOR also supported)
    -format            The output format for tables [basic, plain, markdown]. Default is basic.
    -file              Read test output from a file.
    -follow            Follow raw output from go test to stdout.
    -follow-output     Write raw output from go test to a file (takes precedence over -follow).
    -include-timestamp Include timestamps in follow output. 
    -progress          Print a single summary line for each package. Useful for long running test suites.
    -compare           Compare against a previous test output file. (experimental)
    -trimpath          Remove path prefix from package names in output, simplifying their display.
`)
}

func main() {
	flag.Usage = usage

	for _, arg := range os.Args[1:] {
		if arg == "-h" || arg == "--h" {
			usage()
			os.Exit(0)
		}
		if arg == "-v" || arg == "--v" {
			fmt.Fprintln(os.Stdout, "tparse version: (devel)")
			os.Exit(0)
		}
	}

	if err := flag.CommandLine.Parse(os.Args[1:]); err != nil {
		fmt.Fprintf(os.Stderr, "error parsing flags: %v\n", err)
		usage()
		os.Exit(2)
	}

	if os.Getenv("NO_COLOR") != "" {
		config.nocolor = true
	}

	var reader io.Reader
	var followWriter io.Writer

	if config.followOutput != "" {
		f, err := os.Create(config.followOutput)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error creating follow-output file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		followWriter = f
	} else if config.follow {
		followWriter = os.Stdout
	}

	if config.file != "" {
		f, err := os.Open(config.file)
		if err != nil {
			fmt.Fprintf(os.Stderr, "error opening file: %v\n", err)
			os.Exit(1)
		}
		defer f.Close()
		reader = f
	} else {
		stat, _ := os.Stdin.Stat()
		if (stat.Mode() & os.ModeCharDevice) != 0 {
			fmt.Fprintln(os.Stdout, "stdin must be a pipe, or use -file to open a go test output file")
			os.Exit(0)
		}
		reader = os.Stdin
	}

	exitCode, err := run(reader, os.Stdout, followWriter)
	if err != nil {
		fmt.Fprintf(os.Stderr, "error: %v\n", err)
		os.Exit(1)
	}
	os.Exit(exitCode)
}

func packageDisplay(pkg string) string {
	if config.trimpath != "" && strings.HasPrefix(pkg, config.trimpath) {
		pkg = pkg[len(config.trimpath):]
	}
	if config.smallscreen {
		parts := strings.Split(pkg, "/")
		return parts[len(parts)-1]
	}
	return pkg
}

// isHeaderLine returns true if a line is a test result header line (--- FAIL/PASS/SKIP:)
func isHeaderLine(line string) bool {
	stripped := strings.TrimLeft(line, " \t")
	return strings.HasPrefix(stripped, "--- FAIL:") ||
		strings.HasPrefix(stripped, "--- PASS:") ||
		strings.HasPrefix(stripped, "--- SKIP:")
}

// testDepth returns the depth of a test name (0 for top-level, 1 for subtest, etc.)
func testDepth(testName string) int {
	return strings.Count(testName, "/")
}

// formatHeaderLine reformats a "--- FAIL:" header line with depth-based indentation
func formatHeaderLine(line, testName string) string {
	stripped := strings.TrimLeft(line, " \t")
	indent := strings.Repeat("  ", testDepth(testName))
	return indent + stripped
}

func run(reader io.Reader, w io.Writer, followWriter io.Writer) (int, error) {
	events, err := parseEvents(reader, followWriter)
	if err != nil {
		return 1, err
	}

	if len(events) == 0 {
		fmt.Fprintln(w, "no parsable events: Make sure to run go test with -json flag")
		return 1, nil
	}

	packages := processEvents(events)

	if len(packages) == 0 {
		fmt.Fprintln(w, "no parsable events: Make sure to run go test with -json flag")
		return 1, nil
	}

	sortedPkgs := sortPackages(packages)

	color := newColor(config.nocolor)

	failCount := 0

	if config.format == "markdown" {
		return runMarkdown(w, sortedPkgs, color)
	}

	// Basic/plain format

	// Print test table (for -all, -pass, -skip flags)
	printTestTable := config.all || config.pass || config.skip
	if printTestTable {
		printTestTableBasic(w, sortedPkgs, color)
	}

	// Print package failure/panic output and progress
	for _, pkg := range sortedPkgs {
		if pkg.IsPanic {
			// Progress
			if config.progress {
				fmt.Fprintf(w, "[PANIC]\t%9.2fs\t%s\n", pkg.Elapsed, packageDisplay(pkg.Package))
			}
			printPanicBox(w, pkg, color)
			failCount++
			continue
		}

		// Progress output
		if config.progress {
			statusStr := "PASS"
			if pkg.Status == StatusFail {
				statusStr = "FAIL"
			}
			fmt.Fprintf(w, "[%s]\t%9.2fs\t%s\n", statusStr, pkg.Elapsed, packageDisplay(pkg.Package))
		}

		if pkg.Status == StatusFail || hasFailedTests(pkg) {
			printFailBox(w, pkg, color)
			if pkg.Status == StatusFail {
				failCount++
			}
		}
	}

	// Print final summary table
	printSummaryTable(w, sortedPkgs, color)

	if failCount > 0 {
		return 1, nil
	}
	return 0, nil
}

func runMarkdown(w io.Writer, sortedPkgs []*PackageResult, color *ColorCode) (int, error) {
	failCount := 0

	// Print per-package test summaries
	for _, pkg := range sortedPkgs {
		if pkg.IsNoTest || pkg.IsPanic {
			continue
		}
		showTests := config.all || config.pass || config.skip || pkg.Status == StatusFail || hasFailedTests(pkg)
		if !showTests {
			continue
		}

		var testsToShow []*TestResult
		for _, tr := range pkg.Tests {
			if shouldShowTest(tr) {
				testsToShow = append(testsToShow, tr)
			}
		}

		if len(testsToShow) == 0 && pkg.Status != StatusFail && !hasFailedTests(pkg) {
			continue
		}

		fmt.Fprintf(w, "## 📦 Package **`%s`**\n\n", packageDisplay(pkg.Package))

		passCount := 0
		skipCount := 0
		failC := 0
		for _, tr := range pkg.Tests {
			switch tr.Status {
			case StatusPass:
				passCount++
			case StatusSkip:
				skipCount++
			case StatusFail:
				failC++
			}
		}
		fmt.Fprintf(w, "Tests: ✓ %d passed | %d skipped | %d failed\n\n", passCount, skipCount, failC)

		if len(testsToShow) > 0 {
			fmt.Fprintln(w, "<details>")
			fmt.Fprintln(w, "")
			fmt.Fprintln(w, "<summary>Click for test summary</summary>")
			fmt.Fprintln(w, "")

			tbl := newTable("markdown", color)
			tbl.setHeaders([]string{"Status", "Elapsed", "Test"})
			for _, tr := range testsToShow {
				tbl.addRow([]string{tr.Status.String(), fmt.Sprintf("  %.2f  ", tr.Elapsed), tr.Test})
			}
			tbl.render(w)
			fmt.Fprintln(w, "</details>")
			fmt.Fprintln(w, "")
		}
		fmt.Fprintln(w, "")
	}

	// Print failures
	for _, pkg := range sortedPkgs {
		if pkg.IsPanic {
			continue
		}
		if pkg.Status == StatusFail || hasFailedTests(pkg) {
			statusStr := "FAIL"
			if pkg.Status == StatusPass {
				statusStr = "PASS"
			}
			fmt.Fprintf(w, "## %s • %s\n\n", statusStr, packageDisplay(pkg.Package))
			fmt.Fprintln(w, "```")

			// Get all top-level failed tests (direct tests, not subtests)
			failedTopTests := getTopLevelFailedTests(pkg)
			for _, tr := range failedTopTests {
				printTestOutputForMarkdown(w, pkg, tr)
			}

			fmt.Fprintln(w, "```")
			fmt.Fprintln(w, "")
			if pkg.Status == StatusFail {
				failCount++
			}
		}
	}

	printSummaryTable(w, sortedPkgs, color)

	if failCount > 0 {
		return 1, nil
	}
	return 0, nil
}

func hasFailedTests(pkg *PackageResult) bool {
	for _, tr := range pkg.Tests {
		if tr.Status == StatusFail {
			return true
		}
	}
	return false
}

// getTopLevelFailedTests returns failed tests that are not subtests of another failed test in the package
func getTopLevelFailedTests(pkg *PackageResult) []*TestResult {
	// Create a set of all failed test names
	failedNames := make(map[string]bool)
	for _, tr := range pkg.Tests {
		if tr.Status == StatusFail {
			failedNames[tr.Test] = true
		}
	}

	// A test is "top-level failed" if its parent is not in the failed set
	// and it is either not a subtest, OR its parent is not failed
	var result []*TestResult
	for _, tr := range pkg.Tests {
		if tr.Status != StatusFail {
			continue
		}
		// Check if this test's parent is also failed
		isChild := false
		name := tr.Test
		for {
			idx := strings.LastIndex(name, "/")
			if idx < 0 {
				break
			}
			parent := name[:idx]
			if failedNames[parent] {
				isChild = true
				break
			}
			name = parent
		}
		if !isChild {
			result = append(result, tr)
		}
	}

	// Sort alphabetically
	sort.Slice(result, func(i, j int) bool {
		return result[i].Test < result[j].Test
	})

	return result
}

// shouldShowTest returns true if the test should be shown in the test table
func shouldShowTest(tr *TestResult) bool {
	if config.all {
		return true
	}
	if tr.Status == StatusFail {
		return true
	}
	if config.pass && tr.Status == StatusPass {
		return true
	}
	if config.skip && tr.Status == StatusSkip {
		return true
	}
	return false
}

// getFailedDescendants returns all failed tests that are descendants of parentTest
func getFailedDescendants(pkg *PackageResult, parentTest string) []*TestResult {
	prefix := parentTest + "/"
	var result []*TestResult
	for _, tr := range pkg.Tests {
		if tr.Status == StatusFail && strings.HasPrefix(tr.Test, prefix) {
			result = append(result, tr)
		}
	}
	sort.Slice(result, func(i, j int) bool {
		return result[i].Test < result[j].Test
	})
	return result
}

// printTestFailureOutput prints the failure output for a single top-level failed test
// and its failed descendants
func printTestFailureOutput(w io.Writer, pkg *PackageResult, tr *TestResult) {
	// Print the test's own output header line
	if len(tr.Output) > 0 {
		firstLine := strings.TrimRight(tr.Output[0], "\n")
		if isHeaderLine(firstLine) {
			fmt.Fprintln(w, formatHeaderLine(firstLine, tr.Test))
		} else {
			fmt.Fprintln(w, firstLine)
		}
	} else {
		// No output at all - still try to display header
		fmt.Fprintf(w, "--- FAIL: %s\n", tr.Test)
	}

	// Get all failed descendants, sorted alphabetically
	descendants := getFailedDescendants(pkg, tr.Test)

	// Print all descendants
	for _, child := range descendants {
		printDescendantFailure(w, child)
	}
}

// printDescendantFailure prints the failure for a descendant subtest
func printDescendantFailure(w io.Writer, tr *TestResult) {
	if len(tr.Output) == 0 {
		return
	}

	// Separate header lines from body lines
	var headerLines []string
	var bodyLines []string
	inBody := false

	for _, line := range tr.Output {
		trimmed := strings.TrimRight(line, "\n")
		if !inBody && isHeaderLine(trimmed) {
			headerLines = append(headerLines, trimmed)
		} else {
			inBody = true
			bodyLines = append(bodyLines, trimmed)
		}
	}

	// Print header line(s) with adjusted indent
	for _, h := range headerLines {
		fmt.Fprintln(w, formatHeaderLine(h, tr.Test))
	}

	// Print body if any
	if len(bodyLines) > 0 {
		fmt.Fprintln(w) // blank line after header
		for _, b := range bodyLines {
			fmt.Fprintln(w, b)
		}
		fmt.Fprintln(w) // trailing blank
	}
}

func printTestFailureOutputComplete(w io.Writer, pkg *PackageResult, tr *TestResult) {
	color := newColor(config.nocolor)

	// Print the parent test's own lines
	if len(tr.Output) > 0 {
		for i, line := range tr.Output {
			trimmed := strings.TrimRight(line, "\n")
			if i == 0 && isHeaderLine(trimmed) {
				fmt.Fprintln(w, color.darkRed(formatHeaderLine(trimmed, tr.Test)))
			} else {
				fmt.Fprintln(w, trimmed)
			}
		}
	} else {
		fmt.Fprintf(w, "%s\n", color.darkRed(fmt.Sprintf("--- FAIL: %s", tr.Test)))
	}

	// Get all failed descendants, sorted alphabetically
	descendants := getFailedDescendants(pkg, tr.Test)

	for _, child := range descendants {
		if len(child.Output) == 0 {
			continue
		}

		// Separate header from body
		var headerLines []string
		var bodyLines []string
		inBody := false

		for _, line := range child.Output {
			trimmed := strings.TrimRight(line, "\n")
			if !inBody && isHeaderLine(trimmed) {
				headerLines = append(headerLines, trimmed)
			} else {
				inBody = true
				bodyLines = append(bodyLines, trimmed)
			}
		}

		for _, h := range headerLines {
			fmt.Fprintln(w, color.darkRed(formatHeaderLine(h, child.Test)))
		}

		if len(bodyLines) > 0 {
			fmt.Fprintln(w) // blank after header
			for _, b := range bodyLines {
				fmt.Fprintln(w, b)
