func printTestTableBasic(w io.Writer, packages []*PackageResult, color *ColorCode) {
	// Collect all tests to show, grouped by package, in the right order
	// Within each package: sorted by status (PASS < SKIP < FAIL), then insertion order

	type testEntry struct {
		pkg    *PackageResult
		test   *TestResult
		newPkg bool
	}

	var allTests []testEntry
	prevPkg := ""

	for _, pkg := range packages {
		if pkg.IsNoTest || pkg.IsPanic {
			continue
		}

		// Sort tests: PASS first, then SKIP, then FAIL; within each group: insertion order
		sorted := sortTestsByStatus(pkg.Tests)

		hasPrintable := false
		for _, tr := range sorted {
			if !shouldShowTest(tr) {
				continue
			}
			entry := testEntry{
				pkg:  pkg,
				test: tr,
			}
			if prevPkg != "" && pkg.Package != prevPkg {
				entry.newPkg = true
			}
			if prevPkg == "" || pkg.Package != prevPkg {
				prevPkg = pkg.Package
			}
			if entry.newPkg && len(allTests) > 0 {
				allTests = append(allTests, testEntry{pkg: pkg, test: nil})
			}
			allTests = append(allTests, entry)
			hasPrintable = true
		}
		_ = hasPrintable
	}

	if len(allTests) == 0 {
		return
	}

	// Apply slow filter
	if config.slow > 0 {
		// Keep only top N by elapsed time
		realTests := make([]testEntry, 0)
		for _, e := range allTests {
			if e.test != nil {
				realTests = append(realTests, e)
			}
		}
		sort.SliceStable(realTests, func(i, j int) bool {
			return realTests[i].test.Elapsed > realTests[j].test.Elapsed
		})
		if config.slow < len(realTests) {
			realTests = realTests[:config.slow]
		}
		allTests = realTests
	}

	tbl := newTable(config.format, color)
	tbl.setHeaders([]string{"Status", "Elapsed", "Test", "Package"})

	for _, e := range allTests {
		if e.test == nil {
			// Separator row
			tbl.addRow([]string{"", "", "", ""})
			continue
		}
		tbl.addRow([]string{
			color.statusColor(e.test.Status),
			fmt.Sprintf("%.2f", e.test.Elapsed),
			e.test.Test,
			packageDisplay(e.pkg.Package),
		})
	}

	tbl.render(w)
}

// sortTestsByStatus sorts tests by status (PASS < SKIP < FAIL), preserving insertion order within each group
func sortTestsByStatus(tests []*TestResult) []*TestResult {
	result := make([]*TestResult, len(tests))
	copy(result, tests)

	statusOrder := func(s TestStatus) int {
		switch s {
		case StatusPass:
			return 0
		case StatusSkip:
			return 1
		case StatusFail:
			return 2
		default:
			return 3
		}
	}

	// Stable sort to preserve insertion order within each group
	sort.SliceStable(result, func(i, j int) bool {
		oi := statusOrder(result[i].Status)
		oj := statusOrder(result[j].Status)
		return oi < oj
	})

	return result
}

func printFailBox(w io.Writer, pkg *PackageResult, color *ColorCode) {
	statusStr := "FAIL"
	if pkg.Status == StatusPass {
		statusStr = "PASS"
	}

	content := fmt.Sprintf("   %s  package: %s   ", statusStr, pkg.Package)
	border := strings.Repeat("━", utf8.RuneCountInString(content))

	fmt.Fprintf(w, "%s\n", color.steelBlue("┏"+border+"┓"))
	fmt.Fprintf(w, "%s   %s  package: %s   %s\n",
		color.steelBlue("┃"),
		color.red(statusStr),
		pkg.Package,
		color.steelBlue("┃"))
	fmt.Fprintf(w, "%s\n", color.steelBlue("┗"+border+"┛"))
	fmt.Fprintln(w) // blank line after box

	// Get top-level failed tests
	failedTopTests := getTopLevelFailedTests(pkg)

	for i, tr := range failedTopTests {
		if i > 0 {
			// Separator between failures
			fmt.Fprintln(w, strings.Repeat("─", 96))
			fmt.Fprintln(w, strings.Repeat(" ", 96))
		}
		printTestOutput(w, pkg, tr)
	}
}

func printPanicBox(w io.Writer, pkg *PackageResult, color *ColorCode) {
	testPart := ""
	if pkg.PanicTest != "" {
		testPart = " • " + pkg.PanicTest
	}

	content := fmt.Sprintf("   PANIC  package: %s%s   ", pkg.Package, testPart)
	border := strings.Repeat("━", utf8.RuneCountInString(content))

	fmt.Fprintf(w, "%s\n", color.steelBlue("┏"+border+"┓"))
	fmt.Fprintf(w, "%s   %s  package: %s%s   %s\n",
		color.steelBlue("┃"),
		color.red("PANIC"),
		pkg.Package,
		testPart,
		color.steelBlue("┃"))
	fmt.Fprintf(w, "%s\n", color.steelBlue("┗"+border+"┛"))

	for _, line := range pkg.Output {
		fmt.Fprint(w, line)
	}
	fmt.Fprintln(w)
}

func printSummaryTable(w io.Writer, packages []*PackageResult, color *ColorCode) {
	tbl := newTable(config.format, color)
	tbl.setHeaders([]string{"Status", "Elapsed", "Package", "Cover", "Pass", "Fail", "Skip"})

	for _, pkg := range packages {
		var statusStr, passStr, failStr, skipStr, coverStr string

		if pkg.IsPanic {
			statusStr = color.statusColor(StatusPanic)
			passStr = "--"
			failStr = "--"
			skipStr = "--"
			coverStr = "--"
		} else if pkg.IsNoTest {
			statusStr = color.statusColor(StatusNoTest)
			passStr = "--"
			failStr = "--"
			skipStr = "--"
			coverStr = "--"
		} else {
			statusStr = color.statusColor(pkg.Status)
			passStr = fmt.Sprintf("%d", pkg.Pass)
			failStr = fmt.Sprintf("%d", pkg.Fail)
			skipStr = fmt.Sprintf("%d", pkg.Skip)
			coverStr = pkg.Cover
			if coverStr == "" {
				coverStr = "--"
			}
		}

		elapsed := fmt.Sprintf("%.2fs", pkg.Elapsed)
		pkgName := packageDisplay(pkg.Package)

		tbl.addRow([]string{statusStr, elapsed, pkgName, coverStr, passStr, failStr, skipStr})

		if pkg.IsNoTest {
			msg := "[no test files]"
			for _, line := range pkg.Output {
				line = strings.TrimSpace(line)
				if strings.Contains(line, "[no test files]") {
					break
				}
				if strings.Contains(line, "[no tests to run]") {
					msg = "[no tests to run]"
					break
				}
			}
			tbl.addRow([]string{"", "", msg, "", "", "", ""})
		}
	}

	tbl.render(w)
}

func sortPackages(packages map[string]*PackageResult) []*PackageResult {
	result := make([]*PackageResult, 0, len(packages))
	for _, pkg := range packages {
		result = append(result, pkg)
	}

	switch config.sort {
	case "elapsed":
		sort.Slice(result, func(i, j int) bool {
			return result[i].Elapsed > result[j].Elapsed
		})
	case "cover":
		sort.Slice(result, func(i, j int) bool {
			ci := parseCover(result[i].Cover)
			cj := parseCover(result[j].Cover)
			return ci > cj
		})
	default: // "name"
		sort.Slice(result, func(i, j int) bool {
			return result[i].Package < result[j].Package
		})
	}

	return result
}

func parseCover(s string) float64 {
	if s == "" || s == "--" {
		return -1
	}
	s = strings.TrimSuffix(s, "%")
	var f float64
	fmt.Sscanf(s, "%f", &f)
	return f
}

func parseEvents(reader io.Reader, followWriter io.Writer) ([]*TestEvent, error) {
	var events []*TestEvent
	scanner := bufio.NewScanner(reader)
	scanner.Buffer(make([]byte, 1024*1024), 1024*1024)

	for scanner.Scan() {
		line := scanner.Text()
		if line == "" {
			continue
		}

		var event TestEvent
		if err := json.Unmarshal([]byte(line), &event); err != nil {
			continue
		}

		events = append(events, &event)

		if followWriter != nil && event.Action == "output" {
			if config.includeTimestamp {
				timestamp := event.Time.UTC().Format("2006-01-02T15:04:05Z")
				fmt.Fprintf(followWriter, "%s %s", timestamp, event.Output)
			} else {
				fmt.Fprint(followWriter, event.Output)
			}
		}
	}

	return events, scanner.Err()
}

func processEvents(events []*TestEvent) map[string]*PackageResult {
	packages := make(map[string]*PackageResult)
	testResults := make(map[string]map[string]*TestResult)

	for _, event := range events {
		pkg := event.Package
		if pkg == "" {
			continue
		}

		if _, ok := packages[pkg]; !ok {
			packages[pkg] = &PackageResult{
				Package: pkg,
				testMap: make(map[string]*TestResult),
			}
			testResults[pkg] = make(map[string]*TestResult)
		}

		pkgResult := packages[pkg]

		switch event.Action {
		case "run":
			if event.Test != "" {
				tr := &TestResult{
					Package: pkg,
					Test:    event.Test,
					Status:  StatusUnknown,
				}
				testResults[pkg][event.Test] = tr
				pkgResult.testMap[event.Test] = tr
			}

		case "output":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					tr.Output = append(tr.Output, event.Output)
				}
			} else {
				pkgResult.Output = append(pkgResult.Output, event.Output)
				if strings.Contains(event.Output, "coverage:") {
					cov := extractCoverage(event.Output)
					if cov != "" {
						pkgResult.Cover = cov
					}
				}
			}

		case "pass":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					tr.Status = StatusPass
					tr.Elapsed = event.Elapsed
					pkgResult.Tests = append(pkgResult.Tests, tr)
					pkgResult.Pass++
				}
			} else {
				pkgResult.Status = StatusPass
				pkgResult.Elapsed = event.Elapsed
			}

		case "fail":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					// Check for panic in test output
					hasPanic := false
					for _, line := range tr.Output {
						if strings.HasPrefix(strings.TrimSpace(line), "panic:") {
							hasPanic = true
							break
						}
					}
					if hasPanic {
						pkgResult.IsPanic = true
						pkgResult.PanicTest = event.Test
						pkgResult.Output = append(tr.Output, pkgResult.Output...)
					} else {
						tr.Status = StatusFail
						tr.Elapsed = event.Elapsed
						pkgResult.Tests = append(pkgResult.Tests, tr)
						pkgResult.Fail++
					}
				}
			} else {
				pkgResult.Elapsed = event.Elapsed
				if !pkgResult.IsPanic {
					pkgResult.Status = StatusFail
				}
			}

		case "skip":
			if event.Test != "" {
				tr := testResults[pkg][event.Test]
				if tr != nil {
					tr.Status = StatusSkip
					tr.Elapsed = event.Elapsed
					pkgResult.Tests = append(pkgResult.Tests, tr)
					pkgResult.Skip++
				}
			} else {
				pkgResult.IsNoTest = true
				pkgResult.Status = StatusSkip
				pkgResult.Elapsed = event.Elapsed
			}

		case "build-fail":
			pkgResult.Status = StatusFail
			pkgResult.Fail = 1
		}
	}

	// Handle unfinished tests (tests that had run but no result)
	for _, pkgResult := range packages {
		for testName, tr := range pkgResult.testMap {
			if tr.Status == StatusUnknown {
				// Check if it's in the Tests list already
				found := false
				for _, t := range pkgResult.Tests {
					if t.Test == testName {
						found = true
						break
					}
				}
				if !found {
					tr.Status = StatusFail
					pkgResult.Tests = append(pkgResult.Tests, tr)
					pkgResult.Fail++
				}
			}
		}
	}

	// Check package-level output for panics
	for _, pkgResult := range packages {
		if !pkgResult.IsPanic {
			for _, line := range pkgResult.Output {
				if strings.HasPrefix(strings.TrimSpace(line), "panic:") {
					pkgResult.IsPanic = true
					pkgResult.Status = StatusPanic
					break
				}
			}
		}
		if pkgResult.IsPanic {
			pkgResult.Status = StatusPanic
		}
	}

	return packages
}

func extractCoverage(output string) string {
	idx := strings.Index(output, "coverage: ")
	if idx < 0 {
		return ""
	}
	rest := output[idx+len("coverage: "):]
	end := strings.Index(rest, " ")
	if end < 0 {
		return strings.TrimSpace(rest)
	}
	return rest[:end]
}
