# - Package output contains "panic:" -> IsPanic = true

# But in this case, the PanicTest should be empty (not TestFoo), since TestFoo didn't cause the panic.

# Wait but the FAIL box shows the PANIC header without a test name. That's because:
# pkgResult.IsPanic is set when package-level output contains "panic:"
# The PanicTest is empty since no test's output contained "panic:"

# So my logic is: if package output has "panic:", IsPanic=true but PanicTest=""

# Now let me update my printPanicBox to handle:
# 1. Pad box lines to 96 chars
# 2. Expand tabs in output lines
# 3. Pad output lines to 96 chars
# 4. Trailing blank line padded to 96 chars

# Also: PANIC elapsed should be 0.00s (not the package elapsed)

# Let me update the code

cat > /home/agent/tparse/panic.go << 'GOEOF'
package main

import (
	"fmt"
	"io"
	"strings"
	"unicode/utf8"
)

const panicWidth = 96

func padToWidth(s string, width int) string {
	sLen := utf8.RuneCountInString(s)
	if sLen >= width {
		return s
	}
	return s + strings.Repeat(" ", width-sLen)
}

func expandTabs(s string) string {
	var result strings.Builder
	col := 0
	for _, r := range s {
		if r == '\t' {
			spaces := 8 - (col % 8)
			result.WriteString(strings.Repeat(" ", spaces))
			col += spaces
		} else if r == '\n' {
			result.WriteRune(r)
			col = 0
		} else {
			result.WriteRune(r)
			col++
		}
	}
	return result.String()
}

func printPanicBoxNew(w io.Writer, pkg *PackageResult, color *ColorCode) {
	testPart := ""
	if pkg.PanicTest != "" {
		testPart = " • " + pkg.PanicTest
	}

	content := fmt.Sprintf("   PANIC  package: %s%s   ", pkg.Package, testPart)
	border := strings.Repeat("━", utf8.RuneCountInString(content))

	topLine := "┏" + border + "┓"
	midLine := fmt.Sprintf("┃   %s  package: %s%s   ┃",
		color.red("PANIC"),
		pkg.Package,
		testPart)
	botLine := "┗" + border + "┛"

	fmt.Fprintln(w, padToWidth(color.steelBlue(topLine), panicWidth+len(color.steelBlue(topLine))-len(topLine)))
	fmt.Fprintln(w, padToWidth(
		color.steelBlue("┃")+midLine[1:len(midLine)-1]+color.steelBlue("┃"),
		panicWidth + len(color.steelBlue("┃")*2)-2))
	fmt.Fprintln(w, padToWidth(color.steelBlue(botLine), panicWidth+len(color.steelBlue(botLine))-len(botLine)))

	for _, line := range pkg.Output {
		line = strings.TrimRight(line, "\n")
		line = expandTabs(line)
		fmt.Fprintln(w, padToWidth(line, panicWidth))
	}
	fmt.Fprintln(w, strings.Repeat(" ", panicWidth))
}
GOEOF

