	midLine := color.steelBlue("┃") + "   " + color.red("PANIC") + "  package: " + pkg.Package + testPart + "   " + color.steelBlue("┃")
	botLine := color.steelBlue("┗"+border+"┛")

	fmt.Fprintln(w, padToVisibleWidth(topLine, panicOutputWidth))
	fmt.Fprintln(w, padToVisibleWidth(midLine, panicOutputWidth))
	fmt.Fprintln(w, padToVisibleWidth(botLine, panicOutputWidth))

	for _, line := range pkg.Output {
		line = strings.TrimRight(line, "\n")
		line = expandTabs(line)
		fmt.Fprintln(w, padToVisibleWidth(line, panicOutputWidth))
	}
	// Trailing blank padded to width
	fmt.Fprintln(w, strings.Repeat(" ", panicOutputWidth))
}
GOEOF

