package main

import (
    "fmt"
    "os"
    "strings"
    "text/tabwriter"
)

func center(s string, width int) string {
    if len(s) >= width {
        return s
    }
    total := width - len(s)
    left := total / 2
    right := total - left
    return strings.Repeat(" ", left) + s + strings.Repeat(" ", right)
}

func main() {
    // Test tabwriter with AlignRight
    for _, padding := range []int{1, 2, 3} {
        for _, alignRight := range []bool{true, false} {
            fmt.Printf("padding=%d, alignRight=%v:\n", padding, alignRight)
            var flag uint
            if alignRight {
                flag = tabwriter.AlignRight
            }
            w := tabwriter.NewWriter(os.Stdout, 0, 0, padding, ' ', flag)
            fmt.Fprintln(w, "Status\tElapsed\tTest\tPackage")
            fmt.Fprintln(w, "\t\t\t")
            fmt.Fprintln(w, "SKIP\t0.10\tTestBar\tgithub.com/example/pkg")
            fmt.Fprintln(w, "FAIL\t0.10\tTestFoo\tgithub.com/example/pkg")
            w.Flush()
            fmt.Println()
        }
    }

    // Also test center-aligned tabwriter 
    fmt.Println("Manual center with padding=3:")
    w := tabwriter.NewWriter(os.Stdout, 0, 0, 3, ' ', tabwriter.AlignRight)
    fmt.Fprintln(w, center("Status", 6)+"\t"+center("Elapsed", 7)+"\t"+center("Test", 7)+"\t"+center("Package", 22))
    fmt.Fprintln(w, "\t\t\t")
    fmt.Fprintln(w, center("SKIP", 6)+"\t"+center("0.10", 7)+"\t"+center("TestBar", 7)+"\t"+center("github.com/example/pkg", 22))
    w.Flush()
}
EOF
